class ExtendedDocUnit(BaseDocUnit):
    section_number: Optional[str] = Field(
        None, description="The section number of the document unit, e.g., '1', '1.2', '2.3.1'."
    )
    page_number: Optional[int] = Field(
        None, description="The page number where this document unit appears."
    )
    figure_refs: Optional[List[str]] = Field(
        None, description="List of figure identifiers referenced in this document unit."
    )
    table_refs: Optional[List[str]] = Field(
        None, description="List of table identifiers referenced in this document unit."
    )

class ExtendedDoc(BaseDoc[ExtendedDocUnit]):
    authors: Optional[List[str]] = Field(
        None, description="List of authors of the document."
    )
    publication_date: Optional[str] = Field(
        None, description="The publication date of the document in ISO format (YYYY-MM-DD)."
    )
    keywords: Optional[List[str]] = Field(
        None, description="List of keywords describing the main topics of the document."
    )
    figures: Optional[dict] = Field(
        None, description="Mapping of figure identifiers to their captions."
    )
    tables: Optional[dict] = Field(
        None, description="Mapping of table identifiers to their captions."
    )
    references: Optional[List[str]] = Field(
        None, description="List of bibliographic references cited in the document."
    )
